## 复现用例源码

文件名：`test_aclnn_foreach_addcmul_scalar_int32.cpp`

```cpp
/**
 * FEACMS-INT32 — foreach_addcmul_scalar int32 scalar float24 roundtrip.
 * out = x1 + scalar * x2 * x3
 * int32: x1=0, x2=1, x3=1; scalar=16777217 (=2^24+1)
 * expect exact 16777217; buggy float path → 16777216
 * N=1 (not TP-007 list-cap).
 */
#include <cstdint>
#include <cstdio>
#include <vector>

#include "acl/acl.h"
#include "aclnnop/aclnn_foreach_addcmul_scalar.h"

#define CHECK_RET(cond, return_expr) \
    do { if (!(cond)) { return_expr; } } while (0)
#define LOG_PRINT(message, ...) do { printf(message, ##__VA_ARGS__); } while (0)

static constexpr int32_t kScalar = 16777217;  // 2^24+1
static constexpr int32_t kExpect = 16777217;
static constexpr int32_t kBuggy = 16777216;   // float mantissa truncate

static int Init(int32_t deviceId, aclrtStream* stream)
{
    auto ret = aclInit(nullptr);
    CHECK_RET(ret == ACL_SUCCESS, LOG_PRINT("aclInit failed. ERROR: %d\n", ret); return ret);
    ret = aclrtSetDevice(deviceId);
    CHECK_RET(ret == ACL_SUCCESS, LOG_PRINT("aclrtSetDevice failed. ERROR: %d\n", ret); return ret);
    ret = aclrtCreateStream(stream);
    CHECK_RET(ret == ACL_SUCCESS, LOG_PRINT("aclrtCreateStream failed. ERROR: %d\n", ret); return ret);
    return 0;
}

static int CreateInt32ScalarTensor(int32_t hostVal, void** deviceAddr, aclTensor** tensor)
{
    std::vector<int64_t> shape = {1};
    std::vector<int64_t> strides = {1};
    auto ret = aclrtMalloc(deviceAddr, sizeof(int32_t), ACL_MEM_MALLOC_HUGE_FIRST);
    CHECK_RET(ret == ACL_SUCCESS, LOG_PRINT("aclrtMalloc failed. ERROR: %d\n", ret); return ret);
    ret = aclrtMemcpy(*deviceAddr, sizeof(int32_t), &hostVal, sizeof(int32_t), ACL_MEMCPY_HOST_TO_DEVICE);
    CHECK_RET(ret == ACL_SUCCESS, LOG_PRINT("aclrtMemcpy H2D failed. ERROR: %d\n", ret); return ret);
    *tensor = aclCreateTensor(shape.data(), shape.size(), ACL_INT32, strides.data(), 0, ACL_FORMAT_ND,
                              shape.data(), shape.size(), *deviceAddr);
    CHECK_RET(*tensor != nullptr, LOG_PRINT("aclCreateTensor failed\n"); return 1);
    return 0;
}

int main()
{
    int32_t deviceId = 0;
    aclrtStream stream;
    auto ret = Init(deviceId, &stream);
    CHECK_RET(ret == ACL_SUCCESS, return 1);

    LOG_PRINT("FEACMS-INT32: N=1 int32 addcmul; scalar=%d expect=%d buggy_float=%d\n",
              kScalar, kExpect, kBuggy);
    LOG_PRINT("formula: out = x1 + scalar * x2 * x3 = 0 + %d * 1 * 1\n", kScalar);

    void *dX1 = nullptr, *dX2 = nullptr, *dX3 = nullptr, *dOut = nullptr, *dScalar = nullptr;
    aclTensor *tX1 = nullptr, *tX2 = nullptr, *tX3 = nullptr, *tOut = nullptr, *tScalar = nullptr;

    ret = CreateInt32ScalarTensor(0, &dX1, &tX1);
    CHECK_RET(ret == 0, return 1);
    ret = CreateInt32ScalarTensor(1, &dX2, &tX2);
    CHECK_RET(ret == 0, return 1);
    ret = CreateInt32ScalarTensor(1, &dX3, &tX3);
    CHECK_RET(ret == 0, return 1);
    ret = CreateInt32ScalarTensor(-999, &dOut, &tOut);
    CHECK_RET(ret == 0, return 1);
    ret = CreateInt32ScalarTensor(kScalar, &dScalar, &tScalar);
    CHECK_RET(ret == 0, return 1);

    aclTensor* arrX1[] = {tX1};
    aclTensor* arrX2[] = {tX2};
    aclTensor* arrX3[] = {tX3};
    aclTensor* arrOut[] = {tOut};
    aclTensorList* lX1 = aclCreateTensorList(arrX1, 1);
    aclTensorList* lX2 = aclCreateTensorList(arrX2, 1);
    aclTensorList* lX3 = aclCreateTensorList(arrX3, 1);
    aclTensorList* lOut = aclCreateTensorList(arrOut, 1);
    CHECK_RET(lX1 && lX2 && lX3 && lOut, LOG_PRINT("aclCreateTensorList failed\n"); return 1);

    uint64_t workspaceSize = 0;
    aclOpExecutor* executor = nullptr;
    ret = aclnnForeachAddcmulScalarGetWorkspaceSize(lX1, lX2, lX3, tScalar, lOut, &workspaceSize, &executor);
    LOG_PRINT("GetWorkspaceSize ret=%d wsSize=%llu\n", ret, (unsigned long long)workspaceSize);
    if (ret != ACL_SUCCESS) {
        LOG_PRINT("\nVERDICT: NO_REPRO / blocked (GetWorkspaceSize ret=%d)\n", ret);
        // cleanup abbreviated via finalize path
        aclDestroyTensorList(lX1); aclDestroyTensorList(lX2); aclDestroyTensorList(lX3); aclDestroyTensorList(lOut);
        aclDestroyTensor(tX1); aclDestroyTensor(tX2); aclDestroyTensor(tX3); aclDestroyTensor(tOut); aclDestroyTensor(tScalar);
        aclrtFree(dX1); aclrtFree(dX2); aclrtFree(dX3); aclrtFree(dOut); aclrtFree(dScalar);
        aclrtDestroyStream(stream); aclrtResetDevice(deviceId); aclFinalize();
        return 0;
    }

    void* workspaceAddr = nullptr;
    if (workspaceSize > 0) {
        ret = aclrtMalloc(&workspaceAddr, workspaceSize, ACL_MEM_MALLOC_HUGE_FIRST);
        CHECK_RET(ret == ACL_SUCCESS, LOG_PRINT("workspace malloc failed %d\n", ret); return 1);
    }

    ret = aclnnForeachAddcmulScalar(workspaceAddr, workspaceSize, executor, stream);
    LOG_PRINT("aclnnForeachAddcmulScalar ret=%d\n", ret);
    CHECK_RET(ret == ACL_SUCCESS, LOG_PRINT("launch failed\n"); return 1);
    ret = aclrtSynchronizeStream(stream);
    CHECK_RET(ret == ACL_SUCCESS, LOG_PRINT("sync failed\n"); return 1);

    int32_t actual = 0;
    ret = aclrtMemcpy(&actual, sizeof(int32_t), dOut, sizeof(int32_t), ACL_MEMCPY_DEVICE_TO_HOST);
    CHECK_RET(ret == ACL_SUCCESS, LOG_PRINT("D2H failed\n"); return 1);

    LOG_PRINT("\n| field | expected | actual |\n|-------|----------|--------|\n");
    LOG_PRINT("| out[0] | %d | %d |\n", kExpect, actual);
    LOG_PRINT("| buggy_float24 | %d | (ref) |\n", kBuggy);

    if (workspaceAddr) aclrtFree(workspaceAddr);
    aclDestroyTensorList(lX1); aclDestroyTensorList(lX2); aclDestroyTensorList(lX3); aclDestroyTensorList(lOut);
    aclDestroyTensor(tX1); aclDestroyTensor(tX2); aclDestroyTensor(tX3); aclDestroyTensor(tOut); aclDestroyTensor(tScalar);
    aclrtFree(dX1); aclrtFree(dX2); aclrtFree(dX3); aclrtFree(dOut); aclrtFree(dScalar);
    aclrtDestroyStream(stream); aclrtResetDevice(deviceId); aclFinalize();

    if (actual == kBuggy && actual != kExpect) {
        LOG_PRINT("\nVERDICT: BUG_REPRODUCED (exit 42) float24 roundtrip\n");
        return 42;
    }
    if (actual == kExpect) {
        LOG_PRINT("\nVERDICT: NO_REPRO (exact int32 result)\n");
        return 0;
    }
    LOG_PRINT("\nVERDICT: unexpected actual=%d → exit 1\n", actual);
    return 1;
}
```

